begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select '00000000-0000-0000-0000-000000000000',('d0280200-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'authenticated','authenticated','trip-friend-'||n||'@example.test','',now(),'{"provider":"email","providers":["email"]}','{"display_name":"Trip friend QA"}',now(),now()from generate_series(1,4)n;
create temp table tf(k text primary key,v uuid);grant all on tf to authenticated;
insert into tf select 'a'||n,p.id from generate_series(1,4)n join public.participants p on p.auth_user_id=('d0280200-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;
create function pg_temp.id(key text)returns uuid language sql as $$select v from tf where k=$1$$;
create function pg_temp.claim(n int,guest boolean default false)returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub','d0280200-0000-4000-8000-'||lpad(n::text,12,'0'),'role','authenticated','is_anonymous',guest)::text,true);end$$;
select is(has_table_privilege('authenticated','public.trip_friend_requests','INSERT'),false,'no direct request inserts');
select is(has_table_privilege('authenticated','public.trip_friend_requests','UPDATE'),false,'no direct request updates');
select is(has_table_privilege('authenticated','private.trip_friend_command_receipts','SELECT'),false,'no receipt exposure');
select is(has_function_privilege('anon','public.send_trip_friend_request(uuid,uuid,uuid)','EXECUTE'),false,'anonymous send denied');
select is(has_function_privilege('anon','public.respond_trip_friend_request(uuid,text,integer)','EXECUTE'),false,'anonymous response denied');
set local role authenticated;select pg_temp.claim(1);
insert into tf values('trip',create_space('trip','Friend request trip',null,null,'MYR'));
insert into tf values('group',create_space('group','Existing group',null,null,'MYR'));
reset role;
insert into public.space_members(space_id,participant_id,role)values(pg_temp.id('trip'),pg_temp.id('a2'),'view'),(pg_temp.id('trip'),pg_temp.id('a3'),'full_access');
set local role authenticated;select pg_temp.claim(1);
select throws_ok($$select send_trip_friend_request(null,pg_temp.id('a2'),pg_temp.id('trip'))$$,'P0001','friend_request_unavailable','requires command key');
select throws_ok($$select send_trip_friend_request(gen_random_uuid(),pg_temp.id('a1'),pg_temp.id('trip'))$$,'P0001','friend_request_unavailable','self request denied');
select throws_ok($$select send_trip_friend_request(gen_random_uuid(),pg_temp.id('a4'),pg_temp.id('trip'))$$,'P0001','friend_request_unavailable','target must currently belong to source');
select throws_ok($$select send_trip_friend_request(gen_random_uuid(),pg_temp.id('a2'),pg_temp.id('group'))$$,'P0001','friend_request_unavailable','not a Group feature');
insert into tf values('command',gen_random_uuid());
insert into tf values('request',send_trip_friend_request(pg_temp.id('command'),pg_temp.id('a2'),pg_temp.id('trip')));
select is(send_trip_friend_request(pg_temp.id('command'),pg_temp.id('a2'),pg_temp.id('trip')),pg_temp.id('request'),'same command same result');
select throws_ok($$select send_trip_friend_request(pg_temp.id('command'),pg_temp.id('a3'),pg_temp.id('trip'))$$,'P0001','request_payload_mismatch','command cannot target another pair');
select is((select count(*)from trip_friend_requests),1::bigint,'one request');
select is((select count(*)from friendships),0::bigint,'pending is not friendship');
select is((select count(*)from person_relationships),0::bigint,'pending creates no Person');
select throws_ok($$select respond_trip_friend_request(pg_temp.id('request'),'accepted',1)$$,'P0001','friend_request_unavailable','sender cannot accept');
select pg_temp.claim(3);
select is((select count(*)from trip_friend_requests),0::bigint,'third member cannot read private graph');
select throws_ok($$select respond_trip_friend_request(pg_temp.id('request'),'accepted',1)$$,'P0001','friend_request_unavailable','even another member cannot accept');
select pg_temp.claim(2);
select is(send_trip_friend_request(gen_random_uuid(),pg_temp.id('a1'),pg_temp.id('trip')),pg_temp.id('request'),'cross request coalesces without auto acceptance');
select is((select status from trip_friend_requests where id=pg_temp.id('request')),'pending','explicit consent still required');
select throws_ok($$select respond_trip_friend_request(pg_temp.id('request'),'cancelled',1)$$,'P0001','friend_request_unavailable','target cannot cancel sender request');
select throws_ok($$select respond_trip_friend_request(pg_temp.id('request'),'accepted',99)$$,'P0001','version_conflict','version protected');
select lives_ok($$select respond_trip_friend_request(pg_temp.id('request'),'accepted',1)$$,'target accepts');
select lives_ok($$select respond_trip_friend_request(pg_temp.id('request'),'accepted',1)$$,'accepted retry is idempotent');
select is((select count(*)from friendships where status='accepted'),1::bigint,'one real friendship');
select is((select count(*)from person_relationships),1::bigint,'target sees their own linked Person');
select pg_temp.claim(1);
select is((select count(*)from person_relationships),1::bigint,'sender sees their own linked Person');
select is(send_trip_friend_request(pg_temp.id('command'),pg_temp.id('a2'),pg_temp.id('trip')),pg_temp.id('request'),'send retry after acceptance reconciles receipt');
select lives_ok($$select remove_space_member(pg_temp.id('trip'),pg_temp.id('a2'))$$,'remove original membership');
select pg_temp.claim(2);
select is((select count(*)from friendships where status='accepted'),1::bigint,'friendship survives leaving source');
select throws_ok($$select get_trip_friend_states(pg_temp.id('trip'))$$,'P0001','space_access_denied','request does not grant continued Trip access');
select pg_temp.claim(1);
insert into tf values('cancel-command',gen_random_uuid());
insert into tf values('cancel',send_trip_friend_request(pg_temp.id('cancel-command'),pg_temp.id('a3'),pg_temp.id('trip')));
select lives_ok($$select respond_trip_friend_request(pg_temp.id('cancel'),'cancelled',1)$$,'sender cancels');
select is(send_trip_friend_request(pg_temp.id('cancel-command'),pg_temp.id('a3'),pg_temp.id('trip')),pg_temp.id('cancel'),'old command cannot revive cancelled request');
select pg_temp.claim(3);
select throws_ok($$select respond_trip_friend_request(pg_temp.id('cancel'),'accepted',1)$$,'P0001','friend_request_unavailable','old accept cannot revive cancelled request');
select pg_temp.claim(1);
insert into tf values('decline',send_trip_friend_request(gen_random_uuid(),pg_temp.id('a3'),pg_temp.id('trip')));
select pg_temp.claim(3);select respond_trip_friend_request(pg_temp.id('decline'),'declined',1);
select pg_temp.claim(1);
select throws_ok($$select send_trip_friend_request(gen_random_uuid(),pg_temp.id('a3'),pg_temp.id('trip'))$$,'P0001','friend_request_unavailable','decline cooldown prevents immediate harassment');
select pg_temp.claim(1,true);
select throws_ok($$select send_trip_friend_request(gen_random_uuid(),pg_temp.id('a3'),pg_temp.id('trip'))$$,'P0001','permanent_account_required','anonymous identity denied');
select pg_temp.claim(4);
select throws_ok($$select get_trip_friend_states(pg_temp.id('trip'))$$,'P0001','space_access_denied','unrelated identity cannot enumerate');
select * from finish();rollback;
